  const centres = names.map((n) => ({ n, y: box(inst.parts[n]).getCenter(new THREE.Vector3()).y }));
  centres.sort((a, b) => a.y - b.y);
  const GAP = 0.34;
  centres.forEach((c, i) => { inst.parts[c.n].position.y += i * GAP; });
  inst.group.updateMatrixWorld(true);
  return { order: centres.map((c) => c.n), top: box(inst.group).max.y };
})()
